<?php
require_once 'config.php';require_role('admin');if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('admin.php');}verify_csrf();$id=filter_input(INPUT_POST,'application_id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$allowed=['Submitted','Under Review','Shortlisted','Rejected','Accepted'];if(!$id||!in_array($status,$allowed,true)){flash('error','Please choose a valid application status.');redirect('admin.php');}$s=$pdo->prepare('UPDATE applications a JOIN jobs j ON a.job_id=j.id SET a.status=? WHERE a.id=? AND j.posted_by=?');$s->execute([$status,$id,current_user()['id']]);flash($s->rowCount()?'success':'error',$s->rowCount()?'Application status updated.':'No changes were made.');redirect('admin.php');
